export function parseInteger(chars: number[]): number {
  if (chars.length === 0) {
    throw new RangeError("empty");
  }
  let sign = 1;
  let start = 0;
  if (chars[0] === 45) {
    sign = -1;
    start = 1;
    if (chars.length === 1) {
      throw new RangeError("lone minus");
    }
  }
  let value = 0;
  for (const c of chars.slice(start)) {
    if (c < 48 || c > 57) {
      throw new RangeError("not a digit");
    }
    value = value * 10 + (c - 48);
  }
  return sign * value;
}

import { test } from "node:test";
import assert from "node:assert/strict";
import { parseInteger } from "./parse_int.js";

test("parseInteger", () => {
  assert.equal(parseInteger([49, 50, 51]), 123);
  assert.equal(parseInteger([45, 55]), -7);
  assert.throws(() => parseInteger([]), RangeError);
  assert.throws(() => parseInteger([45]), RangeError);
  assert.throws(() => parseInteger([49, 120]), RangeError);
});
